def sync_to_huggingface(ckpt_file: Path, metrics: dict) -> None:
    try:
        from huggingface_hub import HfApi

        api = HfApi(token=HF_TOKEN)
        api.upload_file(
            path_or_fileobj=str(ckpt_file),
            path_in_repo="checkpoint_latest.pkl",
            repo_id=HF_REPO_ID,
            repo_type="model",
        )
        metrics_path = ckpt_file.parent / "metrics.json"
        with open(metrics_path, "w") as mf:
            json.dump(metrics, mf, indent=2)
        api.upload_file(
            path_or_fileobj=str(metrics_path),
            path_in_repo="metrics.json",
            repo_id=HF_REPO_ID,
            repo_type="model",
        )
        print(f"[HF Sync] Checkpoint and metrics backed up to {HF_REPO_ID}")
    except Exception as e:
        print(f"[HF Sync] Warning: Could not upload to Hugging Face: {e}")


def ensure_all_params(loaded_params: dict, fallback_params: dict) -> dict:
    if isinstance(loaded_params, dict) and "params" in loaded_params and "params" in fallback_params:
        merged = dict(loaded_params["params"])
        for k, v in fallback_params["params"].items():
            if k not in merged:
                merged[k] = v
        return {"params": merged}
    return loaded_params


def load_initial_params(checkpoint_dir: Path, fallback_params: dict) -> dict:
    try:
        from huggingface_hub import hf_hub_download

        cache_dir = checkpoint_dir / "hf_cache"
        cache_dir.mkdir(parents=True, exist_ok=True)
        local_path = hf_hub_download(
            repo_id=HF_REPO_ID,
            filename="checkpoint_latest.pkl",
            token=HF_TOKEN,
            cache_dir=str(cache_dir),
        )
        with open(local_path, "rb") as f:
            params = pickle.load(f)
        print(f"[Init] Loaded latest PPO checkpoint from Hugging Face ({HF_REPO_ID})")
        return ensure_all_params(params, fallback_params)
    except Exception as e:
        print(f"[Init] No PPO checkpoint on Hugging Face: {e}")

    candidates = [
        checkpoint_dir / "checkpoint_latest.pkl",
        Path(__file__).resolve().parent / "checkpoint_latest.pkl",
        Path(__file__).resolve().parent / "checkpoints" / "checkpoint_latest.pkl",
        Path("./checkpoints/checkpoint_latest.pkl"),
        Path("/kaggle/src/checkpoint_latest.pkl"),
        Path("/kaggle/src/checkpoints/checkpoint_latest.pkl"),
    ]
    for cand in candidates:
        if cand.exists():
            with open(cand, "rb") as f:
                print(f"[Init] Loaded local checkpoint from: {cand}")
                return ensure_all_params(pickle.load(f), fallback_params)

    try:
        from huggingface_hub import hf_hub_download

        cache_dir = checkpoint_dir / "hf_cache"
        cache_dir.mkdir(parents=True, exist_ok=True)
        local_path = hf_hub_download(
            repo_id=HF_REPO_ID,
            filename="bc_checkpoint_latest.pkl",
            token=HF_TOKEN,
            cache_dir=str(cache_dir),
        )
        with open(local_path, "rb") as f:
            params = pickle.load(f)
        print(f"[Init] Loaded BC baseline checkpoint from Hugging Face ({HF_REPO_ID})")
        return ensure_all_params(params, fallback_params)
    except Exception as e:
        print(f"[Init] No BC checkpoint on Hugging Face: {e}")

    bc_ckpt = checkpoint_dir / "bc_checkpoint_latest.pkl"
    if bc_ckpt.exists():
        with open(bc_ckpt, "rb") as f:
            print(f"[Init] Loaded local BC checkpoint: {bc_ckpt}")
            return ensure_all_params(pickle.load(f), fallback_params)

    print("[Init] Using freshly initialized model parameters.")
    return fallback_params


