def compute_gae(
    rewards: jnp.ndarray,  # (T, B)
    values: jnp.ndarray,  # (T, B)
    next_value: jnp.ndarray,  # (B,)
    dones: jnp.ndarray,  # (T, B)
    gamma: float = 0.99,
    lam: float = 0.95,
) -> Tuple[jnp.ndarray, jnp.ndarray]:
    """
    Computes Generalized Advantage Estimation (GAE).
    """
    T = rewards.shape[0]
    advantages = []
    gae = jnp.zeros_like(next_value)

    for t in reversed(range(T)):
        non_terminal = 1.0 - dones[t].astype(jnp.float32)
        v_next = next_value if t == T - 1 else values[t + 1]
        delta = rewards[t] + gamma * v_next * non_terminal - values[t]
        gae = delta + gamma * lam * non_terminal * gae
        advantages.insert(0, gae)

    advantages = jnp.stack(advantages, axis=0)  # (T, B)
    returns = advantages + values
    return advantages, returns


def train_ppo_selfplay(
    num_envs: int = 512,
    rollout_len: int = 32,
    total_updates: int = 10,
    lr: float = 2.5e-4,
    clip_eps: float = 0.2,
    entropy_coef: float = 0.05,
    checkpoint_interval_sec: float = 1800.0,
    checkpoint_dir: Optional[Path] = None,
    seed: int = 42,
    heuristic_opponent_fraction: float = 0.40,
    league_opponent_fraction: float = 0.15,
    checkpoint_pool_size: int = 10,
    pool_snapshot_interval: int = 20,
    ppo_epochs: int = 4,
) -> Dict:
    if checkpoint_dir is None:
        checkpoint_dir = Path("/kaggle/working") if os.path.exists("/kaggle/working") else Path("./checkpoints")
    checkpoint_dir.mkdir(parents=True, exist_ok=True)
    latest_ckpt_file = checkpoint_dir / "checkpoint_latest.pkl"

    rng = jax.random.PRNGKey(seed)
    model = ChronosTransformer()

    subkeys = jax.random.split(rng, num_envs)

    def init_single_env(key):
        k1, k2 = jax.random.split(key)
        p1_sp, p2_sp, p1_mv, p2_mv = sample_battle_teams(k1)
        return init_battle_randomized(k2, p1_sp, p2_sp, p1_mv, p2_mv, True)

    states = jax.vmap(init_single_env)(subkeys)

    sample_state = jax.tree_util.tree_map(lambda x: x[:1], states)
    sample_inp = batch_state_to_model_inputs(sample_state, 0)
    rng, init_key = jax.random.split(rng)
    params = model.init(init_key, sample_inp)
    params = load_initial_params(checkpoint_dir, params)

    num_minibatches_estimate = max(1, (num_envs * rollout_len) // 2048)
    lr_schedule = optax.cosine_decay_schedule(
        init_value=lr,
        decay_steps=total_updates * num_minibatches_estimate,
        alpha=0.1,  # final LR = 10% of initial
    )

    optimizer = optax.chain(
        optax.clip_by_global_norm(0.5),
        optax.adamw(learning_rate=lr_schedule, weight_decay=1e-4),
    )
    opt_state = optimizer.init(params)

    # Environment slicing: self-play vs expert heuristic benchmark opponent
    num_heuristic_envs = int(num_envs * heuristic_opponent_fraction)
    num_selfplay_envs = num_envs - num_heuristic_envs
    past_checkpoints_pool = [jax.tree_util.tree_map(lambda x: jnp.copy(x), params)]
    print(
        f"[*] Configured environments: total={num_envs} | "
        f"selfplay={num_selfplay_envs} ({100 - int(heuristic_opponent_fraction * 100)}%) | "
        f"expert_heuristic_benchmark={num_heuristic_envs} ({int(heuristic_opponent_fraction * 100)}%)"
    )

    def ppo_loss(
        p,
        batch_inp,
        batch_acts,
        old_log_probs,
        advantages,
        returns,
        valid_masks,
        batch_opp_acts,
        valid_opp_masks,
        aux_opp_coef=0.25,
        za_coef=0.005,
    ):
        logits, probs, values, raw_opp_logits = model.apply(
            p, batch_inp, valid_mask=valid_masks, deterministic=False, return_opp_action=True
        )
        log_probs = jax.nn.log_softmax(logits, axis=-1)
        action_log_probs = jnp.take_along_axis(log_probs, batch_acts[:, None], axis=-1).squeeze(-1)

        ratio = jnp.exp(action_log_probs - old_log_probs)
        surr1 = ratio * advantages
        surr2 = jnp.clip(ratio, 1.0 - clip_eps, 1.0 + clip_eps) * advantages
        policy_loss = -jnp.mean(jnp.minimum(surr1, surr2))

        val_loss = 0.5 * jnp.mean((values.squeeze(-1) - returns) ** 2)
        entropy = -jnp.mean(jnp.sum(probs * jnp.log(jnp.maximum(probs, 1e-8)), axis=-1))

        # 1. Opponent action auxiliary prediction loss conditioned on valid opponent moves
        masked_opp_logits = jnp.where(valid_opp_masks, raw_opp_logits, -1e9)
        opp_log_probs = jax.nn.log_softmax(masked_opp_logits, axis=-1)
        opp_act_log_probs = jnp.take_along_axis(opp_log_probs, batch_opp_acts[:, None], axis=-1).squeeze(-1)
        opp_loss = -jnp.mean(opp_act_log_probs)

        # 2. Zero-avoiding regularization: -za_coef * mean(log(pi(s, a))) on valid actions
        valid_mask_float = valid_masks.astype(jnp.float32)
        num_valid = jnp.maximum(jnp.sum(valid_mask_float, axis=-1), 1.0)
        za_penalty = -jnp.mean(jnp.sum(valid_mask_float * jnp.log(jnp.maximum(probs, 1e-7)), axis=-1) / num_valid)

        total_loss = (
            policy_loss + 0.5 * val_loss - entropy_coef * entropy + aux_opp_coef * opp_loss + za_coef * za_penalty
        )

        return total_loss, (policy_loss, val_loss, entropy, opp_loss, za_penalty)

    @jax.jit
    def update_step(p, opt_s, batch_inp, batch_acts, old_log_p, advs, rets, v_masks, batch_opp_acts, v_opp_masks):
        grads, (pol_l, val_l, ent, opp_l, za_pen) = jax.grad(ppo_loss, has_aux=True)(
            p, batch_inp, batch_acts, old_log_p, advs, rets, v_masks, batch_opp_acts, v_opp_masks
        )
        updates, opt_s = optimizer.update(grads, opt_s, p)
        p = optax.apply_updates(p, updates)
        return p, opt_s, pol_l, val_l, ent, opp_l, za_pen

    @jax.jit
    def collect_rollout(p, cur_st, key):
        def scan_step(carry, _):
            st, k = carry
            k1, k2, kn = jax.random.split(k, 3)

            inp1 = batch_state_to_model_inputs(st, 0)
            m1 = jax.vmap(get_valid_actions_mask)(st)[:, 0]
            log1, prob1, val1 = model.apply(p, inp1, valid_mask=m1)
            act1 = jax.random.categorical(k1, log1)

            inp2 = batch_state_to_model_inputs(st, 1)
            m2 = jax.vmap(get_valid_actions_mask)(st)[:, 1]

            if num_heuristic_envs == 0:
                log2, _, _ = model.apply(p, inp2, valid_mask=m2)
                act2 = jax.random.categorical(k2, log2)
            elif num_heuristic_envs == num_envs:
                act2 = jax.vmap(heuristic_bot_action, in_axes=(0, None))(st, 1)
            else:
                inp2_sp = jax.tree_util.tree_map(lambda x: x[:num_selfplay_envs], inp2)
                m2_sp = m2[:num_selfplay_envs]
                log2_sp, _, _ = model.apply(p, inp2_sp, valid_mask=m2_sp)
                act2_sp = jax.random.categorical(k2, log2_sp)

                st_heur = jax.tree_util.tree_map(lambda x: x[num_selfplay_envs:], st)
                act2_heur = jax.vmap(heuristic_bot_action, in_axes=(0, None))(st_heur, 1)

                act2 = jnp.concatenate([act2_sp, act2_heur], axis=0)

            nst, rew, don = batch_step_autoreset_randomized(st, act1, act2)

            lp = jax.nn.log_softmax(log1, axis=-1)
            alp = jnp.take_along_axis(lp, act1[:, None], axis=-1).squeeze(-1)

            step_out = {
                "inp1": inp1,
                "act1": act1,
                "act2": act2,
                "alp": alp,
                "rew": rew,
                "val1": val1.squeeze(-1),
                "don": don,
                "m1": m1,
                "m2": m2,
            }
            return (nst, kn), step_out

        (next_st, next_k), traj = jax.lax.scan(scan_step, (cur_st, key), None, length=rollout_len)
        return next_st, next_k, traj

    session_start_time = time.time()
    last_checkpoint_time = session_start_time
    for update in range(1, total_updates + 1):
        start_t = time.perf_counter()

        states, rng, traj = collect_rollout(params, states, rng)

        last_inp = batch_state_to_model_inputs(states, 0)
        _, _, next_v = model.apply(params, last_inp)
        advantages, returns = compute_gae(traj["rew"], traj["val1"], next_v.squeeze(-1), traj["don"])
        advantages = (advantages - jnp.mean(advantages)) / (jnp.std(advantages) + 1e-8)

        flat_acts = traj["act1"].reshape(-1)
        flat_opp_acts = traj["act2"].reshape(-1)
        flat_log_p = traj["alp"].reshape(-1)
        flat_adv = advantages.reshape(-1)
        flat_ret = returns.reshape(-1)
        flat_masks = traj["m1"].reshape(-1, 9)
        flat_opp_masks = traj["m2"].reshape(-1, 9)
        flat_inp = {k: v.reshape((-1,) + v.shape[2:]) for k, v in traj["inp1"].items()}

        batch_size = flat_acts.shape[0]
        minibatch_size = min(2048, batch_size)
        num_minibatches = max(1, batch_size // minibatch_size)

        pol_losses, val_losses, entropies, opp_losses, za_pens = [], [], [], [], []
        for _ in range(ppo_epochs):
            rng, perm_key = jax.random.split(rng)
            perm = jax.random.permutation(perm_key, batch_size)

            for mb_idx in range(num_minibatches):
                mb_inds = perm[mb_idx * minibatch_size : (mb_idx + 1) * minibatch_size]
                mb_inp = {k: v[mb_inds] for k, v in flat_inp.items()}
                params, opt_state, mb_pol_l, mb_val_l, mb_ent, mb_opp_l, mb_za_pen = update_step(
                    params,
                    opt_state,
                    mb_inp,
                    flat_acts[mb_inds],
                    flat_log_p[mb_inds],
                    flat_adv[mb_inds],
                    flat_ret[mb_inds],
                    flat_masks[mb_inds],
                    flat_opp_acts[mb_inds],
                    flat_opp_masks[mb_inds],
                )
                pol_losses.append(mb_pol_l)
                val_losses.append(mb_val_l)
                entropies.append(mb_ent)
                opp_losses.append(mb_opp_l)
                za_pens.append(mb_za_pen)

        pol_l = jnp.mean(jnp.array(pol_losses))
        val_l = jnp.mean(jnp.array(val_losses))
        ent = jnp.mean(jnp.array(entropies))
        opp_l = jnp.mean(jnp.array(opp_losses))
        za_pen = jnp.mean(jnp.array(za_pens))

        # Snapshot current parameters into historical league pool periodically
        if update % pool_snapshot_interval == 0:
            past_checkpoints_pool.append(jax.tree_util.tree_map(lambda x: jnp.copy(x), params))
            if len(past_checkpoints_pool) > checkpoint_pool_size:
                past_checkpoints_pool.pop(0)

        elapsed = time.perf_counter() - start_t
        fps = (num_envs * rollout_len) / elapsed
        print(
            f"Update {update:5d} | "
            f"Pol Loss: {float(pol_l):.4f} | "
            f"Val Loss: {float(val_l):.4f} | "
            f"Entropy: {float(ent):.4f} | "
            f"Opp Loss: {float(opp_l):.4f} | "
            f"ZA: {float(za_pen):.4f} | "
            f"FPS: {fps:8,.1f} | Time: {elapsed:.2f}s"
        )

        current_time = time.time()
        if current_time - last_checkpoint_time >= checkpoint_interval_sec or update == total_updates:
            with open(latest_ckpt_file, "wb") as f:
                pickle.dump(params, f)
            print(f"Checkpoint saved: {latest_ckpt_file}")
            last_checkpoint_time = current_time
            metrics = {
                "update": update,
                "total_turns": update * num_envs * rollout_len,
                "pol_loss": float(pol_l),
                "val_loss": float(val_l),
                "entropy": float(ent),
                "opp_loss": float(opp_l),
                "za_penalty": float(za_pen),
                "fps": float(fps),
                "timestamp": current_time,
            }
            sync_to_huggingface(latest_ckpt_file, metrics)

        if current_time - session_start_time >= MAX_SESSION_DURATION_SEC:
            print("[!] Reached safe session duration limit. Saving final checkpoint...")
            with open(latest_ckpt_file, "wb") as f:
                pickle.dump(params, f)
            metrics = {
                "update": update,
                "total_turns": update * num_envs * rollout_len,
                "pol_loss": float(pol_l),
                "val_loss": float(val_l),
                "entropy": float(ent),
                "opp_loss": float(opp_l),
                "za_penalty": float(za_pen),
                "fps": float(fps),
                "timestamp": current_time,
                "final_session": True,
            }
            sync_to_huggingface(latest_ckpt_file, metrics)
            if os.environ.get("AUTO_HANDOFF") == "1":
                trigger_next_kaggle_kernel()
            print("[✓] Session completed and cleanly saved. Exiting session.")
            sys.exit(0)

    return params


def main():
    base_dir = Path(__file__).resolve().parent.parent
    prepare_kaggle_kernel_metadata(base_dir)
    is_tpu = any(d.platform == "tpu" for d in jax.devices())
    default_envs = 512 if is_tpu else 256
    train_ppo_selfplay(
        num_envs=int(os.environ.get("NUM_ENVS", default_envs)),
        rollout_len=int(os.environ.get("ROLLOUT_LEN", 32)),
        total_updates=100000,
        checkpoint_interval_sec=600.0,
        heuristic_opponent_fraction=float(os.environ.get("HEURISTIC_OPPONENT_FRACTION", 0.40)),
        league_opponent_fraction=float(os.environ.get("LEAGUE_OPPONENT_FRACTION", 0.15)),
        checkpoint_pool_size=int(os.environ.get("CHECKPOINT_POOL_SIZE", 10)),
        pool_snapshot_interval=int(os.environ.get("POOL_SNAPSHOT_INTERVAL", 20)),
    )


if __name__ == "__main__":
    main()
